:root {
  --bg: #1a1c2c;
  --panel: #2b2d42;
  --ink: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #e0a800;
  --muted: #a0a4b8;
  --border: #5a5f7d;
  --focus: #ffcd75;
  --shadow: rgba(0, 0, 0, 0.4);
  --font: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 16px;
  background:
    repeating-linear-gradient(0deg, transparent, transparent 7px, rgba(255, 255, 255, 0.03) 7px, rgba(255, 255, 255, 0.03) 8px),
    repeating-linear-gradient(90deg, transparent, transparent 7px, rgba(255, 255, 255, 0.03) 7px, rgba(255, 255, 255, 0.03) 8px),
    var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: min(100%, 420px);
  background: var(--panel);
  border: 4px solid var(--border);
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 24px;
}

h1 {
  margin: 0;
  font-size: 2rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--shadow);
}

.subtitle {
  margin: 4px 0 24px;
  color: var(--muted);
  font-size: 1rem;
}

.field {
  margin: 0 0 20px;
  border: 0;
  padding: 0;
}

.field label,
.field legend {
  display: block;
  margin-bottom: 8px;
  font-weight: 700;
  font-size: 1rem;
  color: var(--ink);
}

input[type="number"] {
  width: 100%;
  padding: 12px 14px;
  font-family: var(--font);
  font-size: 1.125rem;
  color: var(--ink);
  background: #1f2133;
  border: 3px solid var(--border);
  border-radius: 0;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

input[type="number"]::placeholder {
  color: var(--muted);
}

input[type="number"]:hover {
  border-color: var(--accent);
}

input[type="number"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--accent);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  padding: 12px 8px;
  font-family: var(--font);
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--ink);
  background: #1f2133;
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.1s ease, background 0.15s ease, border-color 0.15s ease;
}

.tip-btn:hover {
  background: #2f3350;
  border-color: var(--accent);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translateY(2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #1a1c2c;
  border-color: var(--accent-dark);
}

.tip-btn[aria-pressed="true"]:hover {
  background: var(--accent-dark);
}

.results {
  margin-top: 28px;
  border-top: 4px dashed var(--border);
  padding-top: 20px;
  display: grid;
  gap: 12px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  font-size: 1.125rem;
}

.result-label {
  color: var(--muted);
}

.result-value {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.result-row.total {
  font-size: 1.375rem;
  color: var(--accent);
}

.result-row.total .result-label {
  color: var(--accent);
}

@media (max-width: 380px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .tip-buttons {
    gap: 6px;
  }
  .tip-btn {
    font-size: 1rem;
    padding: 10px 4px;
  }
}

const billInput = document.getElementById('bill');
const peopleInput = document.getElementById('people');
const tipPerPersonEl = document.getElementById('tip-per-person');
const totalPerPersonEl = document.getElementById('total-per-person');
const tipButtons = Array.from(document.querySelectorAll('.tip-btn'));

let selectedTip = 15;

function formatCurrency(value) {
  return '$' + value.toFixed(2);
}

function calculate() {
  const bill = parseFloat(billInput.value);
  const people = parseInt(peopleInput.value, 10);

  if (!Number.isFinite(bill) || bill < 0 || !Number.isFinite(people) || people < 1) {
    tipPerPersonEl.textContent = '—';
    totalPerPersonEl.textContent = '—';
    return;
  }

  const tipTotal = bill * (selectedTip / 100);
  const tipPerPerson = tipTotal / people;
  const totalPerPerson = (bill + tipTotal) / people;

  tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
  totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
}

function setTip(value) {
  selectedTip = value;
  tipButtons.forEach((btn) => {
    btn.setAttribute('aria-pressed', String(Number(btn.dataset.tip) === value));
  });
  calculate();
}

tipButtons.forEach((btn) => {
  btn.addEventListener('click', () => setTip(Number(btn.dataset.tip)));
});

[billInput, peopleInput].forEach((input) => {
  input.addEventListener('input', calculate);
  input.addEventListener('change', calculate);
});

calculate();
